5	
6	# Koin Dependency Injection
7	
8	Pragmatic DI for Kotlin with Koin.
9	
10	## Module Setup
11	
12	```kotlin
13	// AppModule.kt
14	val appModule = module {
15	    // Singletons
16	    single<AppDatabase> { Room.databaseBuilder(...).build() }
17	    single { get<AppDatabase>().userDao() }
18	    
19	    // Factories (new instance each time)
20	    factory { DateFormatter() }
21	}
22	
23	// NetworkModule.kt
24	val networkModule = module {
25	    single<HttpClient> {
26	        HttpClient(OkHttp) {
27	            install(ContentNegotiation) {
28	                json(Json { ignoreUnknownKeys = true })
29	            }
30	        }
31	    }
32	    
33	    single<AuthApi> { AuthApiImpl(get()) }
34	    single<UserApi> { UserApiImpl(get()) }
35	}
36	
37	// FeatureModule.kt
38	val homeModule = module {
39	    // Repository
40	    single<HomeRepository> { HomeRepositoryImpl(get(), get()) }
41	    
42	    // Use Cases
43	    factory { GetItemsUseCase(get()) }
44	    factory { GetItemUseCase(get()) }
45	    
46	    // ViewModel
47	    viewModel { HomeViewModel(get()) }
48	}
49	```
50	
51	## Application Setup
52	
53	```kotlin
54	class MyApp : Application() {
55	    override fun onCreate() {
56	        super.onCreate()
57	        
58	        startKoin {
59	            androidContext(this@MyApp)
60	            modules(
61	                appModule,
62	                networkModule,
63	                homeModule,
64	                detailModule
65	            )
66	        }
67	    }
68	}
69	```
70	
71	## ViewModel Injection
72	
73	```kotlin
74	// In Compose
75	@Composable
76	fun HomeScreen(viewModel: HomeViewModel = koinViewModel()) {
77	    val state by viewModel.state.collectAsStateWithLifecycle()
78	    // ...
79	}
80	
81	// With parameters
82	@Composable
83	fun DetailScreen(itemId: String) {
84	    val viewModel: DetailViewModel = koinViewModel { parametersOf(itemId) }
85	    // ...
86	}
87	
88	// ViewModel definition with params
89	viewModel { params ->
90	    DetailViewModel(
91	        itemId = params.get(),
92	        repository = get()
93	    )
94	}
95	```
96	
97	## Scopes
98	
99	```kotlin
100	// Activity scope
101	val activityModule = module {
102	    scope<MainActivity> {
103	        scoped { NavigationController() }
104	    }
105	}
106	
107	// Usage
108	class MainActivity : AppCompatActivity(), KoinScopeComponent {
109	    override val scope: Scope by activityScope()
110	    
111	    val nav: NavigationController by inject()
112	}
113	```
114	
115	## Qualifiers
116	
117	```kotlin
118	val networkModule = module {
119	    single(named("auth")) { createAuthClient() }
120	    single(named("default")) { createDefaultClient() }
121	}
122	
123	// Usage
124	class UserApi(
125	    @Named("auth") private val client: HttpClient
126	)
127	```
128	
129	## Testing
130	
131	```kotlin
132	class HomeViewModelTest : KoinTest {
133	    
134	    @get:Rule
135	    val koinRule = KoinTestRule.create {
136	        modules(testModule)
137	    }
138	    
139	    private val testModule = module {
140	        single<HomeRepository> { mockk() }
141	        viewModel { HomeViewModel(get()) }
142	    }
143	    
144	    private val viewModel: HomeViewModel by inject()
145	    private val repository: HomeRepository by inject()
146	    
147	    @Test
148	    fun `loads items`() = runTest {
149	        coEvery { repository.getItems() } returns Result.success(listOf())
150	        // ...
151	    }
152	}
153	```
154	
155	---
156	
157	**Remember**: Koin is pragmatic. Keep modules organized, use scopes for lifecycle.
